function normalGrammar(s){return clean(s).replace(/\bdoesn't\b/g,"does not").replace(/\bdon't\b/g,"do not").replace(/\bisn't\b/g,"is not").replace(/\baren't\b/g,"are not").replace(/\bi'm\b/g,"i am")}
function checkGrammar(){if(grammarState.checked)return;const item=ps[grammarState.session].grammar[grammarState.index],ans=normalGrammar(item.answer),got=normalGrammar(grammarState.attempt);if(!got){alert(psT("empty"));return;}grammarState.checked=true;grammarState.status=ans===got?"correct":"wrong";WynnlingAttempts.record(grammarState.index,{prompt:item.prompt,model:item.answer},grammarState.attempt,ans===got,x=>normalGrammar(x)===ans);persist(item.id,{last:grammarState.status,tries:(psHistory[item.id]?.tries||0)+1});psGrammar()}
function grammarWhy(item){
 const answer=item.answer;
 const prompt=item.prompt;
 const subject=prompt.split("______")[0].trim().replace(/[?!.,]+$/g,"");
 const lower=subject.toLowerCase();
 if(/\(be\)/i.test(prompt))return language==="vi"?`Dùng be phù hợp: ${answer}.`:`Use the correct be form: ${answer}.`;
 if(/\b(do|does)\b/.test(answer)&&/\(do\)/i.test(prompt))return language==="vi"?`Câu hỏi hiện tại đơn: ${answer}.`:`Present Simple question: ${answer}.`;
 if(/\bnot\b|n't/.test(answer))return language==="vi"?`Phủ định hiện tại đơn: ${answer}.`:`Present Simple negative: ${answer}.`;
 const simpleSing=/\b(my|his|her|your|the)\s+(?:older |younger |little |elder )?(?:brother|sister|father|mother|friend|teacher|manager|neighbor|company)\b|\b(he|she|it)\b/i.test(subject);
 const rule=simpleSing?"V(s/es)":"V₀";
 return language==="vi"?`${simpleSing?"Chủ ngữ số ít":"Chủ ngữ số nhiều / I / you"} → ${rule}: ${answer}.`:`${simpleSing?"Singular subject":"I/you/plural subject"} → ${rule}: ${answer}.`;
}
